import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabaseClient';
import { apiFetch } from '../../lib/api';
import JobList from '../../components/JobList';

const SAMPLE_PAYLOAD = `{
  "invoice_number": "INV-VND-001",
  "customer_name": "Customer Corp",
  "amount": 12000,
  "notes": "Generated by vendor on behalf of customer"
}`;

const fmt = (n) => `₹${Number(n).toFixed(2)}`;

export default function VendorDashboard() {
  const { user, signOut } = useAuth();
  const [overview, setOverview] = useState(null);
  const [customers, setCustomers] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [pricing, setPricing] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [customerId, setCustomerId] = useState('');
  const [templateId, setTemplateId] = useState('');
  const [format, setFormat] = useState('PDF');
  const [payloadText, setPayloadText] = useState(SAMPLE_PAYLOAD);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [busy, setBusy] = useState(false);
  const [busyJobId, setBusyJobId] = useState(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const loadAll = async () => {
    const [ov, { data: jobData }] = await Promise.all([
      apiFetch('/api/vendor/overview'),
      supabase.from('document_jobs').select('*').order('created_at', { ascending: false }),
    ]);
    setOverview(ov);
    setJobs(jobData ?? []);
  };

  useEffect(() => {
    loadAll().catch((err) => setError(err.message));
    apiFetch('/api/vendor/customers')
      .then(({ customers: list }) => {
        setCustomers(list);
        if (list[0]) setCustomerId(list[0].id);
      })
      .catch((err) => setError(err.message));
    supabase
      .from('templates')
      .select('id, name')
      .eq('is_active', true)
      .then(({ data }) => {
        setTemplates(data ?? []);
        if (data?.[0]) setTemplateId(data[0].id);
      });
    supabase
      .from('pricing_rules')
      .select('format, base_price')
      .then(({ data }) => setPricing(data ?? []));
  }, []);

  const priceOf = (f) => pricing.find((p) => p.format === f);

  const createJob = async (e) => {
    e.preventDefault();
    setError('');
    setNotice('');
    setBusy(true);
    try {
      let payload;
      try {
        payload = JSON.parse(payloadText);
      } catch {
        throw new Error('Payload must be valid JSON');
      }
      const { job } = await apiFetch('/api/jobs', {
        method: 'POST',
        body: JSON.stringify({
          template_id: templateId,
          requested_format: format,
          payload,
          customer_id: customerId,
        }),
      });
      setNotice(
        `Job created for customer — charged ${fmt(job.total_charged)}, your cut ${fmt(job.vendor_cut)}. Now hit Generate.`
      );
      await loadAll();
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  const generate = async (id) => {
    setError('');
    setBusyJobId(id);
    try {
      await apiFetch(`/api/jobs/${id}/generate`, { method: 'POST' });
      await loadAll();
    } catch (err) {
      setError(err.message);
    } finally {
      setBusyJobId(null);
    }
  };

  const download = async (id) => {
    setError('');
    try {
      const { url } = await apiFetch(`/api/jobs/${id}/download`);
      window.open(url, '_blank');
    } catch (err) {
      setError(err.message);
    }
  };

  const requestPayout = async (e) => {
    e.preventDefault();
    setError('');
    setNotice('');
    setBusy(true);
    try {
      const { payout } = await apiFetch('/api/vendor/payouts', {
        method: 'POST',
        body: JSON.stringify({ amount: Number(payoutAmount) }),
      });
      setNotice(`Payout of ${fmt(payout.amount)} requested — funds held until the admin processes it.`);
      setPayoutAmount('');
      await loadAll();
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  const profile = overview?.profile;

  return (
    <div className="max-w-5xl mx-auto mt-10 p-6">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold">Vendor Dashboard</h1>
        <button onClick={signOut} className="text-sm text-red-600 underline">Sign out</button>
      </div>
      <p className="text-gray-600 text-sm">
        {profile?.business_name ?? '—'} · signed in as {user?.email}
      </p>

      {error && <p className="text-red-600 text-sm mt-3">{error}</p>}
      {notice && <p className="text-green-700 text-sm mt-3">{notice}</p>}

      {/* Wallet */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mt-6">
        <div className="p-4 border rounded bg-green-50">
          <div className="text-xs text-gray-500 uppercase">Wallet balance</div>
          <div className="text-2xl font-bold text-green-800">{profile ? fmt(profile.wallet_balance) : '…'}</div>
        </div>
        <div className="p-4 border rounded">
          <div className="text-xs text-gray-500 uppercase">Commission</div>
          <div className="text-lg font-semibold">
            {profile
              ? profile.commission_type === 'PERCENTAGE'
                ? `${profile.commission_rate}% of every job`
                : `${fmt(profile.commission_rate)} per job`
              : '…'}
          </div>
        </div>
        <form onSubmit={requestPayout} className="p-4 border rounded flex items-end gap-2">
          <div className="flex-1">
            <label className="block text-xs text-gray-500 uppercase">Request payout</label>
            <input
              type="number"
              min="1"
              step="0.01"
              value={payoutAmount}
              onChange={(e) => setPayoutAmount(e.target.value)}
              placeholder="Amount (₹)"
              required
              className="w-full p-2 border rounded mt-1"
            />
          </div>
          <button
            type="submit"
            disabled={busy || !payoutAmount}
            className="bg-blue-600 text-white px-4 py-2 rounded font-semibold disabled:opacity-50"
          >
            {busy ? '…' : 'Request'}
          </button>
        </form>
      </div>

      {/* Generate on behalf of customer */}
      <form onSubmit={createJob} className="mt-8 p-4 border rounded bg-gray-50 space-y-4">
        <h2 className="font-semibold">Generate for a customer</h2>
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium">Customer</label>
            <select
              value={customerId}
              onChange={(e) => setCustomerId(e.target.value)}
              className="w-full p-2 border rounded bg-white"
            >
              {customers.map((c) => (
                <option key={c.id} value={c.id}>{c.email}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium">Template</label>
            <select
              value={templateId}
              onChange={(e) => setTemplateId(e.target.value)}
              className="w-full p-2 border rounded bg-white"
            >
              {templates.map((t) => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium">Format</label>
            <select
              value={format}
              onChange={(e) => setFormat(e.target.value)}
              className="w-full p-2 border rounded bg-white"
            >
              {pricing.map((p) => (
                <option key={p.format} value={p.format}>
                  {p.format} — ₹{p.base_price}
                </option>
              ))}
            </select>
          </div>
          <div className="flex items-end">
            <button
              type="submit"
              disabled={busy || !customerId || !templateId}
              className="w-full bg-blue-600 text-white p-2 rounded font-semibold disabled:opacity-50"
            >
              {busy ? 'Creating…' : 'Create job'}
            </button>
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium">Payload (JSON)</label>
          <textarea
            value={payloadText}
            onChange={(e) => setPayloadText(e.target.value)}
            rows={6}
            className="w-full p-2 border rounded font-mono text-xs"
          />
        </div>
      </form>

      <h2 className="font-semibold mt-8">Documents I generated</h2>
      <JobList jobs={jobs} onGenerate={generate} onDownload={download} busyId={busyJobId} showCut />

      {/* Ledger */}
      <h2 className="font-semibold mt-8">Wallet ledger</h2>
      {overview && overview.ledger.length ? (
        <table className="w-full text-sm mt-4 border rounded">
          <thead>
            <tr className="text-left border-b bg-gray-50">
              <th className="p-2">Date</th>
              <th className="p-2">Type</th>
              <th className="p-2">Amount</th>
              <th className="p-2">Balance after</th>
              <th className="p-2">Description</th>
            </tr>
          </thead>
          <tbody>
            {overview.ledger.map((row) => (
              <tr key={row.id} className="border-b">
                <td className="p-2 whitespace-nowrap">{new Date(row.created_at).toLocaleString()}</td>
                <td className="p-2">{row.entry_type}</td>
                <td className={`p-2 font-medium ${Number(row.amount) >= 0 ? 'text-green-700' : 'text-red-600'}`}>
                  {Number(row.amount) >= 0 ? '+' : ''}{fmt(row.amount)}
                </td>
                <td className="p-2">{fmt(row.balance_after)}</td>
                <td className="p-2 text-gray-500">{row.description ?? ''}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p className="text-gray-500 text-sm mt-4">No ledger entries yet.</p>
      )}

      {/* Payouts */}
      <h2 className="font-semibold mt-8">My payout requests</h2>
      {overview && overview.payouts.length ? (
        <table className="w-full text-sm mt-4 border rounded">
          <thead>
            <tr className="text-left border-b bg-gray-50">
              <th className="p-2">Date</th>
              <th className="p-2">Amount</th>
              <th className="p-2">Status</th>
              <th className="p-2">Admin notes</th>
            </tr>
          </thead>
          <tbody>
            {overview.payouts.map((p) => (
              <tr key={p.id} className="border-b">
                <td className="p-2 whitespace-nowrap">{new Date(p.created_at).toLocaleString()}</td>
                <td className="p-2">{fmt(p.amount)}</td>
                <td className="p-2">{p.status}</td>
                <td className="p-2 text-gray-500">{p.admin_notes ?? ''}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p className="text-gray-500 text-sm mt-4">No payout requests yet.</p>
      )}
    </div>
  );
}
